<script lang="ts">import {imageSource} from '#lib/core/image-source.ts';let {src,large=false,quantity,thumbnail=true,eager=false,quality}:{src:string|null|undefined;large?:boolean;quantity?:number|string;thumbnail?:boolean;eager?:boolean;quality?:number|null}=$props();let framed=$derived(quality!=null&&Number.isInteger(quality)&&quality>=1&&quality<=6);</script>
<span class="game-icon" class:large class:item-frame={framed} data-quality={framed?quality:undefined}><img src={imageSource(src,thumbnail&&!large)} alt={src?'':'無原圖，使用備用圖示'} loading={eager?'eager':'lazy'} decoding="async" width={large?96:44} height={large?96:44}>{#if framed}<img class="quality-frame" src={`/ui/quality/${quality}.png`} alt="" aria-hidden="true" width="75" height="75"/>{/if}{#if quantity!==undefined}<span class="stack-count" aria-label={`數量 ${quantity}`}>{quantity}</span>{/if}</span>
<style>.game-icon.item-frame{border:0;background:#090609;box-shadow:none;border-radius:3px;overflow:hidden;isolation:isolate}.item-frame>img:not(.quality-frame){padding:5%;box-sizing:border-box}.item-frame>.quality-frame{position:absolute;inset:0;width:100%;height:100%;padding:0;object-fit:fill;pointer-events:none;z-index:2}.game-icon{position:relative}.stack-count{position:absolute;right:2px;bottom:1px;z-index:3;color:#fff;font:bold 11px/1.2 'Segoe UI',sans-serif;text-shadow:0 1px 2px #000,1px 0 2px #000,-1px 0 2px #000;background:#100d08b3;padding:1px 2px;max-width:100%;white-space:nowrap}</style>

